"use client"
import { useEffect, useRef, useState } from 'react'

type Question = { id:string, text:string }
type InterviewEvaluation = {
  evaluations: { question:string; answer:string; score:number; feedback:string }[]
  total: number
  percentage: number
  summary: string
}

function generateQuestions(topic:string, skill:string, count:number): Question[]{
  const qs:Question[] = []
  for(let i=1;i<=count;i++) qs.push({id:i.toString(), text:`${topic} question ${i} (${skill})`})
  return qs
}

export default function InterviewPage({id}:{id:string}){
  const [course,setCourse] = useState<any|null>(null)
  const [questions,setQuestions] = useState<Question[]>([])
  const [index,setIndex] = useState(0)
  const [answers,setAnswers] = useState<Record<string,string>>({})
  const [evaluation,setEvaluation] = useState<InterviewEvaluation|null>(null)
  const [evaluationError,setEvaluationError] = useState('')
  const [status,setStatus] = useState('Preparing interview...')
  const [sessionStarted,setSessionStarted] = useState(false)
  const [liveMode,setLiveMode] = useState<'ready'|'speaking'|'listening'|'reviewing'|'complete'>('ready')
  const [countdown,setCountdown] = useState(60)
  const recognitionRef = useRef<any>(null)
  const currentAnswerRef = useRef('')
  const phaseRef = useRef<'speaking'|'listening'|'finished'>('finished')
  const startedQuestionRef = useRef('')
  const silenceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const restartTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const resultsTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const indexRef = useRef(0)
  const questionsRef = useRef<Question[]>([])
  const answersRef = useRef<Record<string,string>>({})
  const courseRef = useRef<any|null>(null)
  const introductionStartedRef = useRef(false)
  const closingStartedRef = useRef(false)

  indexRef.current = index
  questionsRef.current = questions
  answersRef.current = answers
  courseRef.current = course

  useEffect(()=>{
    const raw = localStorage.getItem('am_courses')
    if(!raw) return
    const arr = JSON.parse(raw)
    const found = arr.find((x:any)=>x.id===id)
    setCourse(found)
    if(found) setQuestions(found.questions || generateQuestions(found.title,found.skill,found.count))
  },[id])

  function updateLiveMode(mode: 'ready'|'speaking'|'listening'|'reviewing'|'complete', nextStatus:string){
    setLiveMode(mode)
    setStatus(nextStatus)
  }

  function clearSilenceTimer(){
    if(silenceTimerRef.current){
      clearTimeout(silenceTimerRef.current)
      silenceTimerRef.current = null
    }
  }

  function moveToNextQuestion(){
    clearSilenceTimer()
    phaseRef.current = 'speaking'
    recognitionRef.current?.abort?.()
    if(indexRef.current < questionsRef.current.length - 1){
      setIndex(indexRef.current + 1)
    }else{
      finish()
    }
  }

  function startSilenceTimer(){
    clearSilenceTimer()
    silenceTimerRef.current = setTimeout(moveToNextQuestion, 5000)
  }

  useEffect(()=>{
    const win = window as any
    const SR = win.SpeechRecognition || win.webkitSpeechRecognition
    if(!SR){
      updateLiveMode('ready', 'Speech recognition is not supported in this browser. Type your answer below.')
      return
    }

    const rec = new SR()
    rec.lang='en-US'
    rec.interimResults = true
    rec.continuous = true
    rec.onresult = (e:any)=>{
      startSilenceTimer()
      let requestedNext = false
      for(let resultIndex=e.resultIndex; resultIndex<e.results.length; resultIndex++){
        if(!e.results[resultIndex].isFinal) continue
        const transcript = e.results[resultIndex][0].transcript.trim()
        if(!transcript) continue
        const commandMatch = transcript.match(/\b(next question|go to next|move on|next one)\b/i)
        if(commandMatch){
          const answerPart = transcript.replace(commandMatch[0], '').trim()
          if(answerPart) currentAnswerRef.current = `${currentAnswerRef.current} ${answerPart}`.trim()
          requestedNext = true
        }else{
          currentAnswerRef.current = `${currentAnswerRef.current} ${transcript}`.trim()
        }
      }

      const questionId = questionsRef.current[indexRef.current]?.id
      if(questionId){
        const nextAnswers = {...answersRef.current, [questionId]: currentAnswerRef.current}
        answersRef.current = nextAnswers
        setAnswers(nextAnswers)
      }
      if(requestedNext) moveToNextQuestion()
      else {
        updateLiveMode('listening', 'Listening...')
      }
    }
    rec.onerror = (e:any)=>{
      if(e.error === 'not-allowed' || e.error === 'service-not-allowed'){
        phaseRef.current = 'speaking'
        updateLiveMode('ready', 'Microphone permission is required. Type your answer below.')
      }
    }
    rec.onend = ()=>{
      if(phaseRef.current !== 'listening') return
      if(restartTimerRef.current) clearTimeout(restartTimerRef.current)
      restartTimerRef.current = setTimeout(()=>{
        if(phaseRef.current === 'listening'){
          try { rec.start() } catch { /* Recognition is already restarting. */ }
        }
      }, 100)
    }
    rec.onstart = ()=>{
      if(phaseRef.current === 'listening'){
        updateLiveMode('listening', 'Listening...')
      }
    }
    recognitionRef.current = rec

    return ()=>{
      rec.onresult = null
      rec.onend = null
      rec.onerror = null
      rec.onstart = null
      clearSilenceTimer()
      if(restartTimerRef.current) clearTimeout(restartTimerRef.current)
      if(resultsTimerRef.current) clearTimeout(resultsTimerRef.current)
      rec.abort()
    }
  },[])

  function speak(text:string, onEnd?:()=>void){
    const ut = new SpeechSynthesisUtterance(text)
    ut.onend = ()=> onEnd?.()
    window.speechSynthesis.cancel()
    window.speechSynthesis.speak(ut)
  }

  function startListening(){
    const rec = recognitionRef.current
    if(!rec){
      updateLiveMode('ready', 'Type your answer below.')
      return
    }
    phaseRef.current = 'listening'
    updateLiveMode('listening', 'Listening... You can say "next question" when finished.')
    try {
      rec.start()
    } catch {
      updateLiveMode('ready', 'Microphone permission is required. Type your answer below.')
    }
  }

  function finish(){
    if(closingStartedRef.current) return
    closingStartedRef.current = true
    clearSilenceTimer()
    recognitionRef.current?.abort?.()
    phaseRef.current = 'speaking'
    updateLiveMode('reviewing', 'Wrapping up the interview...')
    const showResults = ()=>{
      if(resultsTimerRef.current) clearTimeout(resultsTimerRef.current)
      void evaluateInterview()
    }
    speak(
      'Thank you for completing this mock interview. You did a great job. Goodbye, and here are your results.',
      showResults
    )
    resultsTimerRef.current = setTimeout(showResults, 8000)
  }

  async function evaluateInterview(){
    phaseRef.current = 'finished'
    updateLiveMode('reviewing', 'Gemini is evaluating your interview...')
    setEvaluationError('')

    try {
      const response = await fetch('/api/evaluate-interview', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          topic: courseRef.current?.title,
          skill: courseRef.current?.skill,
          items: questionsRef.current.map(question => ({
            question: question.text,
            answer: answersRef.current[question.id] || ''
          }))
        })
      })
      const result = await response.json()
      if(!response.ok) throw new Error(result.error || 'Unable to evaluate the interview')
      setEvaluation(result)
      setIndex(questionsRef.current.length)
      updateLiveMode('complete', 'Interview complete. Review your results below.')
    } catch (error) {
      setEvaluationError(error instanceof Error ? error.message : 'Unable to evaluate the interview')
      updateLiveMode('ready', 'Evaluation failed. Please try again.')
    }
  }

  function askQuestion(questionIndex:number){
    const question = questionsRef.current[questionIndex]
    if(!question || closingStartedRef.current) return

    startedQuestionRef.current = question.id
    currentAnswerRef.current = answers[question.id] || ''
    phaseRef.current = 'speaking'
    updateLiveMode('speaking', 'Asking question...')
    speak(question.text, startListening)
  }

  useEffect(()=>{
    const q = questions[index]
    if(!course || !q || startedQuestionRef.current === q.id || closingStartedRef.current) return

    if(!introductionStartedRef.current){
      introductionStartedRef.current = true
      setSessionStarted(true)
      phaseRef.current = 'speaking'
      updateLiveMode('speaking', 'Welcome to your mock interview...')
      speak(
        `Welcome to your mock interview for ${course.title}. I will ask you ${questions.length} questions. Take your time, speak naturally, and say next question whenever you are ready to continue.`,
        ()=>askQuestion(0)
      )
      return
    }

    setSessionStarted(true)
    askQuestion(index)
  },[course,questions,index])

  useEffect(()=>{
    if(!sessionStarted || index >= questions.length || evaluation) return
    setCountdown(60)
    const timer = setInterval(()=>{
      setCountdown((current)=>{
        if(current <= 1){
          moveToNextQuestion()
          return 0
        }
        return current - 1
      })
    },1000)
    return ()=> clearInterval(timer)
  },[sessionStarted,index,questions.length,evaluation])

  useEffect(()=>()=>{
    window.speechSynthesis.cancel()
    if(resultsTimerRef.current) clearTimeout(resultsTimerRef.current)
    recognitionRef.current?.abort?.()
  },[])

  const progressValue = questions.length ? ((index + 1) / questions.length) * 100 : 0
  const currentQuestion = questions[index]

  if(!course) return <div style={styles.empty}>Course not found</div>

  if(index>=questions.length && evaluation){
    return (
      <div style={styles.pageShell}>
        <div style={styles.mainCard}>
          <div style={styles.headerRow}>
            <div>
              <div style={styles.kicker}>Interview summary</div>
              <h2 style={styles.h2}>{course.title}</h2>
            </div>
            <div style={styles.scorePill}>{Math.round(evaluation.percentage)}% score</div>
          </div>

          <div style={styles.resultsHero}>
            <div>
              <div style={styles.metricLabel}>Overall performance</div>
              <div style={styles.metricValue}>{Math.round(evaluation.percentage)}%</div>
            </div>
            <div style={{flex:1}}>
              <div style={styles.progressTrack}>
                <div style={{...styles.progressFill, width: `${evaluation.percentage}%`}} />
              </div>
              <div style={styles.metricMeta}>Total score: {evaluation.total} / {questions.length * 10}</div>
            </div>
          </div>

          <div style={styles.summaryBox}>{evaluation.summary}</div>

          <div style={styles.questionList}>
            {evaluation.evaluations.map((result,i)=>(
              <div key={i} style={styles.answerCard}>
                <div style={styles.questionHeading}>Question {i+1}</div>
                <div style={styles.answerTitle}>{result.question || questions[i]?.text}</div>
                <div style={styles.answerRow}><strong>Answer:</strong> {result.answer || answers[questions[i]?.id] || 'No answer provided'}</div>
                <div style={styles.answerRow}><strong>Score:</strong> {result.score} / 10</div>
                <div style={styles.answerRow}><strong>Feedback:</strong> {result.feedback}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    )
  }

  if(index>=questions.length){
    return (
      <div style={styles.pageShell}>
        <div style={styles.mainCard}>
          <div style={styles.kicker}>Interview status</div>
          <h2 style={styles.h2}>{course.title}</h2>
          <div style={styles.loadingState}>{evaluationError || 'Gemini is preparing your results...'}</div>
        </div>
      </div>
    )
  }

  const q = currentQuestion

  return (
    <div style={styles.pageShell}>
      <div style={styles.mainCard}>
        <div style={styles.headerRow}>
          <div>
            <div style={styles.kicker}>Live mock interview</div>
            <h2 style={styles.h2}>{course.title}</h2>
          </div>
          <div style={styles.statusBadge(liveMode)}>{liveMode === 'listening' ? 'Listening' : liveMode === 'speaking' ? 'Speaking' : liveMode === 'reviewing' ? 'Reviewing' : 'Ready'}</div>
        </div>

        <div style={styles.topMetaRow}>
          <div style={styles.metaCard}>
            <div style={styles.metaLabel}>Question</div>
            <div style={styles.metaValue}>{index + 1} / {questions.length}</div>
          </div>
          <div style={styles.metaCard}>
            <div style={styles.metaLabel}>Skill</div>
            <div style={styles.metaValue}>{course.skill || 'General'}</div>
          </div>
          <div style={styles.metaCard}>
            <div style={styles.metaLabel}>Timer</div>
            <div style={styles.metaValue}>{countdown}s</div>
          </div>
        </div>

        <div style={styles.progressTrack}>
          <div style={{...styles.progressFill, width: `${progressValue}%`}} />
        </div>

        <div style={styles.questionPanel}>
          <div style={styles.questionTag}>Prompt</div>
          <div style={styles.questionText}>{q.text}</div>
          <div style={styles.statusLine}>{status}</div>
        </div>

        <div style={styles.answerPanel}>
          <div style={styles.panelHeader}>
            <span>Your answer</span>
            <span style={styles.helperText}>Speak naturally or type here</span>
          </div>
          <textarea
            aria-label="Your answer"
            value={answers[q.id] || ''}
            onChange={e=>{
              const nextAnswers = {...answersRef.current, [q.id]: e.target.value}
              answersRef.current = nextAnswers
              setAnswers(nextAnswers)
            }}
            rows={6}
            style={styles.textarea}
            placeholder="Share your response here..."
          />
        </div>

        <div style={styles.actionRow}>
          <button style={styles.secondaryButton} onClick={()=>{
            if(!q) return
            speak(q.text, startListening)
            updateLiveMode('speaking', 'Repeating question...')
          }}>
            Repeat question
          </button>
          <button style={styles.primaryButton} onClick={()=>{
            if(index < questions.length - 1) setIndex(index + 1)
            else finish()
          }}>
            {index < questions.length - 1 ? 'Next question' : 'Finish interview'}
          </button>
        </div>
      </div>
    </div>
  )
}

